const fs=require('fs'),vm=require('vm'),assert=require('node:assert/strict');
function node(value=''){return {value,disabled:false,children:[],listeners:{},textContent:'',dataset:{},append(...items){this.children.push(...items)},appendChild(item){this.children.push(item)},replaceChildren(){this.children=[]},setAttribute(key,v){this[key]=v},getAttribute(key){return this[key]},setCustomValidity(message){this.validation=message},reportValidity(){return !this.validation}};}
const sources=node('[{"source_type":"document","source_id":"existing"}]'),ids=node('[]');
const selected=node(),selectedIDs=node(),sourceSelect=node('document:new'),understandingSelect=node('understanding-1');sourceSelect.options=[{value:'document:new',textContent:'新资料'}];understandingSelect.options=[{value:'understanding-1',textContent:'我的当前理解'}];
const add=node(),addUnderstanding=node(),save=node(),preview=node();save.name=preview.name='action';save.value='settings';preview.value='preview';
const elements={_csrf:node('csrf'),config_id:node('config'),expected_revision:node('2'),window_capacity:node('50'),input_cents_per_million:node('17'),index_authorized:node('1'),sources,understanding_snapshot_ids:ids};elements.index_authorized.type='checkbox';elements.index_authorized.checked=true;Object.entries(elements).forEach(([name,v])=>v.name=name);
const nodes={'[data-embedding-add]':add,'[data-embedding-add-understanding]':addUnderstanding,'[data-embedding-source]':sourceSelect,'[data-embedding-understanding]':understandingSelect,'[data-embedding-selected]':selected,'[data-embedding-selected-understandings]':selectedIDs};
const form=node();form.elements=elements;form.action='/search/settings';form.querySelector=selector=>nodes[selector];form.querySelectorAll=()=>Object.values(elements).concat(save,preview,add,addUnderstanding);
const view={querySelector:()=>null,querySelectorAll:selector=>selector==='[data-embedding-settings]'||selector==='form[action="/search/settings"]'?[form]:[]};
const requests=[],visits=[];let reply=async()=>({ok:true,json:async()=>[]});const context={AbortController,crypto:{randomUUID:()=> 'new-key'},document:{hidden:false,createElement:()=>node()},CWPViews:{define:fn=>context.mount=fn},CWPNavigation:{visit:async href=>visits.push(href)},FormData:class extends Map{constructor(f){super(Object.values(f.elements).filter(v=>!v.disabled&&(v.type!=='checkbox'||v.checked)).map(v=>[v.name,v.value]))}}};context.window=context;
const scope={signal:new AbortController().signal,on:(n,event,fn)=>n.listeners[event]=fn,interval:()=>{},fetch:async(url,options)=>{requests.push({url,options});return reply(url,options)}};
vm.runInNewContext(fs.readFileSync('static/form-actions.js','utf8'),context);vm.runInNewContext(fs.readFileSync('static/knowledge-search-settings.js','utf8'),context);context.mount(view,scope);
const submit=button=>form.listeners.submit({preventDefault(){},submitter:button});
(async()=>{
 assert.equal(requests.length,0,'mount must not enqueue or update');assert.equal(form.action,'/api/knowledge-search-settings');assert.equal(selected.children[0].children[0].textContent,'document:existing','out-of-picker selection remains visible');
 add.listeners.click();assert.equal(JSON.parse(sources.value).length,2);add.listeners.click();assert.equal(JSON.parse(sources.value).length,2,'duplicate selection is idempotent');selected.children[0].children[1].listeners.click();assert.equal(JSON.parse(sources.value)[0].source_id,'new');
 addUnderstanding.listeners.click();assert.deepEqual(JSON.parse(ids.value),['understanding-1']);
 reply=async()=>({ok:true,json:async()=>[{source_type:'document',source_id:'new',reason:'当前不允许，不会外发。'}]});assert.equal((await submit(preview)).state,'saved');const sent=JSON.parse(requests.at(-1).options.body);assert.equal(sent.action,'preview');assert.deepEqual(sent.understanding_snapshot_ids,['understanding-1']);assert.equal(visits.length,0,'permission preview must preserve form');assert(form.children[0].textContent.includes('不会外发'));
 elements.input_cents_per_million.value='999';reply=async()=>({ok:false,status:409,text:async()=> '配置已改变'});assert.equal((await submit(save)).state,'rejected');assert.equal(elements.input_cents_per_million.value,'999');assert.equal(elements.expected_revision.value,'2');assert.equal(elements.sources.disabled,false);assert.equal(visits.length,0);
 const count=requests.length;sources.value='invalid json';assert.equal((await submit(save)).state,'invalid');assert.equal(requests.length,count,'invalid range cannot submit');
 console.log('embedding settings: explicit add/remove, no mount work, permission preview and CAS input preservation passed');
})().catch(error=>{console.error(error);process.exit(1)});
